		SET @createTbsql = CONCAT('CREATE TABLE ',  tableName, '(
			`d_acct` varchar(10) DEFAULT NULL  ,
			`S_TRECODE` varchar(10) DEFAULT NULL  ,
			`S_TREDSCR` varchar(50) DEFAULT NULL  ,
			`AREA_NO` varchar(10) DEFAULT NULL  ,
			`AREA_DSCR` varchar(20) DEFAULT NULL  ,
			`ETPCODE` varchar(50) DEFAULT NULL  ,
			`ETPNAME` varchar(50) DEFAULT NULL  ,
			`LEV_1_ID` char(1) DEFAULT NULL  ,
			`LEV_1_DSCR` varchar(50) DEFAULT NULL  ,
			`LEV_2_ID` varchar(5) DEFAULT NULL  ,
			`LEV_2_DSCR` varchar(50) DEFAULT NULL  ,
			`LEV_3_ID` varchar(5) DEFAULT NULL  ,
			`LEV_3_DSCR` varchar(50) DEFAULT NULL  ,
			`LEV_4_ID` varchar(5) DEFAULT NULL  ,
			`LEV_4_DSCR` varchar(50) DEFAULT NULL  ,
			`S_BDGSBTCODE` varchar(20) DEFAULT NULL  ,
			`BDGSBTNAME` varchar(100) DEFAULT NULL  ,
			`F_AMT` decimal(18,2) DEFAULT NULL  ,
			KEY `group_index` (`d_acct`,`S_TRECODE`,`ETPNAME`,`LEV_4_ID`,`S_BDGSBTCODE`)
