-- PROCEDURE `edw`.`proc_trs_guoku_cp`
DROP PROCEDURE IF EXISTS `edw`.`proc_trs_guoku_cp`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `proc_trs_guoku_cp`()
BEGIN
  DELETE
  FROM
    adm.`trs_stat_agentbankpay_back_detail`
  WHERE STR_TO_DATE(
      CONCAT_WS(
        '-',
        LEFT(S_ENTRUSTDATE, 4),
        SUBSTR(S_ENTRUSTDATE, 5, 2),
        RIGHT(S_ENTRUSTDATE, 2)
      ),
      '%Y-%m-%d'
    ) = DATE_SUB(CURDATE(), INTERVAL 1 DAY);
  DELETE
  FROM
    adm.`trs_stat_agentbankpay_detail`
  WHERE STR_TO_DATE(
      CONCAT_WS(
        '-',
        LEFT(S_ENTRUSTDATE, 4),
        SUBSTR(S_ENTRUSTDATE, 5, 2),
        RIGHT(S_ENTRUSTDATE, 2)
      ),
      '%Y-%m-%d'
    ) = DATE_SUB(CURDATE(), INTERVAL 1 DAY);
  insert into adm.`trs_stat_agentbankpay_detail`
  select
    *
  from
    ods.`trs_stat_agentbankpay_detail`
  where STR_TO_DATE(
      CONCAT_WS(
        '-',
        LEFT(S_ENTRUSTDATE, 4),
        SUBSTR(S_ENTRUSTDATE, 5, 2),
        RIGHT(S_ENTRUSTDATE, 2)
      ),
      '%Y-%m-%d'
    ) = DATE_SUB(CURDATE(), INTERVAL 1 DAY);
  INSERT INTO adm.`trs_stat_agentbankpay_back_detail`
  SELECT
    *
  FROM
    ods.`trs_stat_agentbankpay_back_detail`
  WHERE STR_TO_DATE(
      CONCAT_WS(
        '-',
        LEFT(S_ENTRUSTDATE, 4),
        SUBSTR(S_ENTRUSTDATE, 5, 2),
        RIGHT(S_ENTRUSTDATE, 2)
      ),
      '%Y-%m-%d'
    ) = DATE_SUB(CURDATE(), INTERVAL 1 DAY);
END
$$
