-- PROCEDURE `edw`.`p_abc_xunhuan`
DROP PROCEDURE IF EXISTS `edw`.`p_abc_xunhuan`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_abc_xunhuan`(IN START_DATE VARCHAR(10),IN END_DATE  VARCHAR(10))
BEGIN
	while date_format(START_DATE,'%Y-%m-%d') <= date_format(END_DATE,'%Y-%m-%d')
	do 
	
			select  CONCAT(date_format(start_date,'%Y%m%d'),'edw--linshi--edw');
			
	    call edw.P_trs_kyd_industry_0911(date_format(START_DATE,'%Y%m%d'));
			
			select  CONCAT(date_format(start_date,'%Y%m%d'),'adm--p_trs_kyd_industry');
			
	    call adm.p_trs_kyd_industry(date_format(START_DATE,'%Y-%m-%d'));
			
			select  CONCAT(date_format(start_date,'%Y%m%d'),'adm--p_trs_kyd_enterprise');
			
	    call adm.p_trs_kyd_enterprise(date_format(START_DATE,'%Y-%m-%d'));
			
			select  CONCAT(date_format(start_date,'%Y%m%d'),'adm--p_trs_kyd_enterprise_rank');
			
	    call adm.p_trs_kyd_enterprise_rank(date_format(START_DATE,'%Y-%m-%d'));
	
	
	
	
	
	select  CONCAT(date_format(start_date,'%Y%m%d'),'结束');
  SET start_date = DATE_ADD(date_format(start_date,'%Y-%m-%d'),INTERVAL 1 month);
        
	 
	END WHILE;
	END
$$
DELIMITER ;

