    ,BALANCE4_SUB_BGY
    ,BALANCE4_TB
    ,BALANCE5
    ,BALANCE5_SUB_BGY
    ,BALANCE5_TB
    ,BALANCE6
    ,BALANCE6_SUB_BGY
    ,BALANCE6_TB
  )
   select 
     NOW()
    ,AREA_NO
    ,DATA_DATE
    ,ORG_NO
    ,ROWS_ID
    ,BALANCE1
    ,BALANCE1_SUB_BGY
    ,BALANCE1_TB
    ,BALANCE2
    ,BALANCE2_SUB_BGY
    ,BALANCE2_TB
    ,BALANCE3
