    ,BALANCE6_TB
   from ods.GLR_EDS_INSURE_IRB_DTL1 
   WHERE DATA_DATE = @V_TEMP_QUA_MONTH
   ;
   CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
   
   
   SET V_STEP_ID = 7;
