-- PROCEDURE `edw`.`P_GLR_EDS_M_SUST_ALL`
DROP PROCEDURE IF EXISTS `edw`.`P_GLR_EDS_M_SUST_ALL`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `P_GLR_EDS_M_SUST_ALL`(IN P_DATA_DATE VARCHAR(10),OUT P_RESULT INT)
BEGIN

	DECLARE V_PROC_NAME  VARCHAR(80)   DEFAULT 'EDW.P_GLR_EDS_M_SUST_ALL.PRC';
	DECLARE V_START_TIME CHAR(19) DEFAULT NOW();
	DECLARE V_STEP_ID    INT  DEFAULT 0;
	DECLARE V_DATA_DATE   VARCHAR(10)   DEFAULT P_DATA_DATE;    
        DECLARE V_DATA_DATE_P VARCHAR(10)   DEFAULT DATE_FORMAT(LAST_DAY(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 1 MONTH)),'%Y%m%d');
	DECLARE V_DATA_DATE_L VARCHAR(10)   DEFAULT DATE_FORMAT(LAST_DAY(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH)),'%Y%m%d');
	
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
           GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
           CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
           SET P_RESULT = 1;
        END ;
        
        
    
    
    SET V_STEP_ID = 1;
    DELETE FROM EDW.GLR_EDS_FINANCE_KEY_KPI_MTH WHERE DATA_DATE = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    SET V_STEP_ID = 2;
    INSERT INTO EDW.GLR_EDS_FINANCE_KEY_KPI_MTH(
	 BATCH_DATE                     
	,AREA_NO                        
	,DATA_DATE                      
	,ORG_NO                         
	,ROWS_ID                        
	,ORG_CODE                       
	,ORG_NAME                       
	,DEP_LOCAL_FOREIGN_BAL          
	,DEP_LOCAL_FOREIGN_BAL_P        
	,DEP_CNY_BAL                    
	,DEP_CNY_BAL_P                  
	,DEP_SAVE_BAL                   
	,DEP_SAVE_BAL_P                 
	,LOAB_LOCAL_FOREIGN_BAL         
	,LOAB_LOCAL_FOREIGN_BAL_P       
	,LOAN_CNY_BAL                   
	,LOAN_CNY_BAL_P                 
	,LOAN_SHORT_BAL                 
	,LOAN_SHORT_BAL_P               
	,LOAN_MID_BAL                   
	,LOAN_MID_BAL_P                 
	,LOAN_PERSON_MID_BAL            
	,LOAN_PERSON_MID_BAL_P          
    )
    SELECT 
         NOW()	
	,AREA_NO                
	,V_DATA_DATE              
	,ORG_NO                 
	,ROWS_ID                
	,ORG_CODE               
	,ORG_NAME               
	,SUM(CASE WHEN t.data_date=V_DATA_DATE THEN DEP_LOCAL_FOREIGN_BAL  ELSE 0 END) AS DEP_LOCAL_FOREIGN_BAL
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN DEP_LOCAL_FOREIGN_BAL ELSE 0 END) AS DEP_LOCAL_FOREIGN_BAL_P
	,SUM(CASE WHEN t.data_date=V_DATA_DATE THEN DEP_CNY_BAL            ELSE  0 END) AS  DEP_CNY_BAL
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN DEP_CNY_BAL ELSE 0 END) AS DEP_CNY_BAL_P
	,SUM(CASE WHEN t.data_date=V_DATA_DATE THEN  DEP_SAVE_BAL ELSE 0 END) AS DEP_SAVE_BAL          
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN DEP_SAVE_BAL ELSE 0 END) AS DEP_SAVE_BAL_P
	,SUM(CASE WHEN t.data_date=V_DATA_DATE   THEN LOAB_LOCAL_FOREIGN_BAL ELSE 0 END) AS LOAB_LOCAL_FOREIGN_BAL
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN LOAB_LOCAL_FOREIGN_BAL ELSE 0 END)AS LOAB_LOCAL_FOREIGN_BAL_P
	,SUM(CASE WHEN t.data_date=V_DATA_DATE   THEN LOAN_CNY_BAL           ELSE 0 END) AS LOAN_CNY_BAL
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN LOAN_CNY_BAL ELSE 0 END) AS LOAN_CNY_BAL_P
	,SUM(CASE WHEN t.data_date=V_DATA_DATE   THEN LOAN_SHORT_BAL      ELSE 0 END) AS LOAN_SHORT_BAL
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN LOAN_SHORT_BAL ELSE 0 END) AS LOAN_SHORT_BAL_P   
	,SUM(CASE WHEN t.data_date=V_DATA_DATE   THEN LOAN_MID_BAL           ELSE 0 END) AS LOAN_MID_BAL
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN LOAN_MID_BAL ELSE 0 END) AS LOAN_MID_BAL_P   
	,SUM(CASE WHEN t.data_date=V_DATA_DATE   THEN LOAN_PERSON_MID_BAL    ELSE 0 END) AS LOAN_PERSON_MID_BAL
	,SUM(CASE WHEN t.data_date=V_DATA_DATE_P THEN LOAN_PERSON_MID_BAL ELSE 0 END) AS LOAN_PERSON_MID_BAL_P   
    FROM ODS.GLR_EDS_FINANCE_KEY_KPI_MTH_DTL1 t
    GROUP BY AREA_NO                
	,ORG_NO                 
	,ROWS_ID                
	,ORG_CODE               
	,ORG_NAME   
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    
    
    SET V_STEP_ID = 3;
    DELETE FROM EDW.GLR_EDS_TECHNOLO_FINANCE_MTH WHERE DATA_DATE = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    SET V_STEP_ID = 4;
    INSERT INTO EDW.GLR_EDS_TECHNOLO_FINANCE_MTH(
	 BATCH_DATE        
	,AREA_NO           
	,DATA_DATE         
	,ORG_NO            
	,ROWS_ID           
	,KPI_NAME          
	,LOAN_BAL          
	,LOAN_BAL_P        
	,VERITY_VAL        
    )
    SELECT 
         NOW()	
	,AREA_NO   
	,DATA_DATE 
	,ORG_NO    
	,ROWS_ID   
	,KPI_NAME  
	,LOAN_BAL  
	,LOAN_BAL_P
	,VERITY_VAL
    FROM ODS.GLR_EDS_TECHNOLO_FINANCE_MTH_DTL1
    WHERE DATA_DATE = v_data_date 
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
END
$$
DELIMITER ;

-- PROCEDURE `edw`.`P_GLR_FARM_M_ALL`
DROP PROCEDURE IF EXISTS `edw`.`P_GLR_FARM_M_ALL`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `P_GLR_FARM_M_ALL`(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT INT)
BEGIN

	DECLARE V_PROC_NAME  VARCHAR(80)   DEFAULT 'EDW.P_GLR_FARM_M_ALL.PRC';
	DECLARE V_START_TIME CHAR(19)      DEFAULT NOW();
	DECLARE V_STEP_ID INT  DEFAULT 0;
	declare V_DATA_DATE VARCHAR(6) DEFAULT SUBSTR(P_DATA_DATE,1,6);
	
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	
        BEGIN
           GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
           CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
           SET P_RESULT = 1;
        END ;
	
	
	SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(P_DATA_DATE,'%Y%m%d')),'Q'),'\'') INTO @v_temp_qua;
        SET @instr = CONCAT('SELECT MAX(T.MONTH) AS MONTH  INTO @V_TEMP_QUA_MONTH  FROM edw.dim_date t WHERE t.QUARTER=',@v_temp_qua,'
        AND t.YEAR = ',SUBSTR(V_DATA_DATE,1,4));
 
        PREPARE smt FROM @instr;
        EXECUTE smt;
        DEALLOCATE PREPARE smt;
	
	SET V_STEP_ID = 1;
	
	DELETE FROM EDW.GLR_AGL_FARM_LOAN WHERE DATA_DATE = V_DATA_DATE;
	CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
	
	SET V_STEP_ID = 2;
	INSERT INTO EDW.GLR_AGL_FARM_LOAN (
	BACH_DATE,
	AREA_NO,
	DATA_DATE,
	ORG_NO,
	ROWS_ID,
	PROJECT,
	LOAN_BAL,
	LOAN_BAL_ZB,
	LOAN_BAL_ADD_NEW,
	LOAN_BAL_ADD_NEW_ZB,
	LOAN_BAL_TB
        )
        SELECT 
           NOW()
          ,AREA_NO
          ,DATA_DATE
          ,ORG_NO
          ,ROWS_ID
          ,PROJECT
          ,BAL_CUR
          ,BAL_EACH_RATE
          ,BAL_CUR_Y
          ,BAL_EACH_RATE_Y
          ,YOY_GROWTH
        FROM ODS.GLR_LFC_SPE_DATA_AGRI_DTL1
        
        WHERE DATA_DATE=V_DATA_DATE
        ;
        CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
        
        
        
        
        SET V_STEP_ID = 3;
        DELETE FROM EDW.GLR_AGL_FARM_ORG_LOAN WHERE DATA_DATE = V_DATA_DATE;
	CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
        
        SET V_STEP_ID = 4;
        INSERT INTO EDW.GLR_AGL_FARM_ORG_LOAN (
	BATCH_DATE,
	AREA_NO,
	DATA_DATE,
	ORG_NO,
	ROWS_ID,
	PROJECT,
	LOAN_BAL,
	LOAN_BAL_P,
	LOAN_BAL_ADD_BGY,
	LOAN_BAL_TB,
	LOAN_BAL_SUB_L,
	LOAN_BAL_L,
	LOAN_BAL_SUB_BGY
       )
       select 
	 NOW()
	,AREA_NO
	,DATA_DATE
	,ORG_NO
	,ROWS_ID
	,PROJECT
	,LOAN_BAL
	,LOAN_BAL_P
	,LOAN_BAL_ADD_BGY
	,LOAN_BAL_TB
	,LOAN_BAL_SUB_L
	,LOAN_BAL_L
	,LOAN_BAL_SUB_BGY
       from ODS.GLR_AGL_FARM_ORG_LOAN_DTL1
       WHERE DATA_DATE=V_DATA_DATE
       ;
       CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
       
       
       
       
       SET V_STEP_ID = 5;
       DELETE FROM EDW.GLR_FRL_HOME_MORTGAGES WHERE DATA_DATE = V_DATA_DATE;
       CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
	
       SET V_STEP_ID = 6;
       INSERT INTO EDW.GLR_FRL_HOME_MORTGAGES (
	BATCH_DATE,
	AREA_NO,
	DATA_DATE,
	ORG_NO,
	ROWS_ID,
	KPI_CODE,
	KPI_NAME,
	BALANCE,
	OCCUR_BALANCE
       )
       SELECT 
         NOW()
        ,AREA_NO
        ,DATA_DATE
        ,ORG_NO
        ,ROWS_ID
        ,KPI_CODE
        ,KPI_NAME
        ,BALANCE
        ,OCCUR_BALANCE
       FROM ODS.GLR_FRL_HOME_MORTGAGES_DTL1
       WHERE DATA_DATE=V_DATA_DATE
       ;
       
       CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
       
       
       SET V_STEP_ID = 7;
       DELETE FROM EDW.GLR_FRL_LAND_MORTGAGES WHERE DATA_DATE = V_DATA_DATE;
       CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
       SET V_STEP_ID = 8;
       INSERT INTO EDW.GLR_FRL_LAND_MORTGAGES (
	BATCH_DATE,
	AREA_NO,
	DATA_DATE,
	ORG_NO,
	ROWS_ID,
	KPI_CODE,
	KPI_NAME,
	BALANCE,
	OCCUR_BALANCE
       )
       
       SELECT 
        NOW()
       ,AREA_NO
       ,DATA_DATE
       ,ORG_NO
       ,ROWS_ID
       ,KPI_CODE
       ,KPI_NAME
       ,BALANCE
       ,OCCUR_BALANCE
       FROM ODS.GLR_FRL_LAND_MORTGAGES_DTL1
       WHERE DATA_DATE=V_DATA_DATE
       ;
       CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
       
       
       SET V_STEP_ID = 9;
       DELETE FROM EDW.GLR_AGL_FARM_BAD_LOAN_CNY WHERE DATA_DATE = @V_TEMP_QUA_MONTH;
       CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
       SET V_STEP_ID = 10;
       INSERT INTO EDW.GLR_AGL_FARM_BAD_LOAN_CNY (
	BATCH_DATE,
	AREA_NO,
	DATA_DATE,
	ORG_NO,
	ROWS_ID,
	KPI_CODE,
	KPI_NAME,
	LOAN_BALANCE
