    DECLARE V_START_TIME CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID INT  DEFAULT 0;
    DECLARE V_DATA_DATE VARCHAR(6) DEFAULT SUBSTR(P_DATA_DATE,1,6);
    
    
    
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    
        BEGIN
           GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
           CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
           SET P_RESULT = 1;
        END ;
        
        
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(P_DATA_DATE,'%Y%m%d')),'Q'),'\'') INTO @v_temp_qua;
        SET @instr = CONCAT('SELECT MAX(T.MONTH) AS MONTH  INTO @V_TEMP_QUA_MONTH  
        FROM edw.dim_date t WHERE t.QUARTER=',@v_temp_qua,'
        AND t.YEAR = ',SUBSTR(V_DATA_DATE,1,4));
 
        PREPARE smt FROM @instr;
        EXECUTE smt;
        DEALLOCATE PREPARE smt;
        
    
    SET V_STEP_ID=1;
    DELETE FROM EDW.GLR_MPA_1411 WHERE DATA_DATE = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    SET V_STEP_ID=2;
    INSERT INTO EDW.GLR_MPA_1411 (
          BATCH_DATE
         ,AREA_NO
         ,DATA_DATE
         ,ORG_NO
         ,ROWS_ID
         ,KPI_CODE
         ,KPI_NAME
         ,BALANCE
         ,BALANCE_P
    )
    SELECT 
             NOW()
         ,AREA_NO
         ,DATA_DATE
         ,ORG_NO
         ,ROWS_ID
         ,KPI_CODE
         ,KPI_NAME
         ,BALANCE
         ,BALANCE_P
    FROM ods.GLR_MPA_1411_DTL1
    WHERE DATA_DATE = V_DATA_DATE
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    
    SET V_STEP_ID=3;
    DELETE FROM EDW.GLR_MPA_CBRC_1104_G01 WHERE DATA_DATE = V_DATA_DATE;
