-- PROCEDURE `edw`.`p_loop`
DROP PROCEDURE IF EXISTS `edw`.`p_loop`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_loop`(in start_date varchar(10),in end_date varchar(10))
BEGIN
while start_date <= end_date
do 
select start_date;
call edw.p_trs_kyd_industry(start_date);
set start_date = date_add(start_date ,interval 1 day);
end while;
    END
$$
DELIMITER ;

-- PROCEDURE `edw`.`p_loop_20241023`
DROP PROCEDURE IF EXISTS `edw`.`p_loop_20241023`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_loop_20241023`(in start_date varchar(10),in end_date varchar(10))
BEGIN
	while start_date <= end_date
	do 
		call edw.p_abc_xunhuan(start_date, end_date);
	end while;
END
$$
DELIMITER ;

-- PROCEDURE `edw`.`P_SAIKU_TPA_AREA_ORG_TYPE`
DROP PROCEDURE IF EXISTS `edw`.`P_SAIKU_TPA_AREA_ORG_TYPE`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `P_SAIKU_TPA_AREA_ORG_TYPE`(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
BEGIN

    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'EDW.P_SAIKU_TPA_AREA_ORG_TYPE.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    DECLARE V_DATA_DATE VARCHAR(6) DEFAULT SUBSTR(P_DATA_DATE,1,6);
    DECLARE V_DATA_DATE_L VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,6);
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    
    SET V_STEP:='1';
    DELETE  FROM EDW.SAIKU_TPA_LOAN_TERM_ORG_TYPE WHERE DATA_DATE = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    
    SET V_STEP:='2';
    INSERT INTO EDW.SAIKU_TPA_LOAN_TERM_ORG_TYPE (
	 BATCH_DATA               
	,DATA_DATE                
	,AREA_CODE                
	,AREA_DESC                
	,ORG_CODE                 
	,ORG_NAME                 
	,TPA_LOAN_TYPE_CODE       
	,TPA_LOAN_TYPE_DESC       
	,LOAN_BAL                 
	,LOAN_BAL_L               
	,LOAN_BAL_Y_ADD           
	,LOAN_BAL_Y               
	,LOAN_BAL_Y_L             
	,LOAN_COUNT               
	,LOAN_PER_COUNT           
     )
     
     SELECT
         NOW()                    AS   BATCH_DATA          
	,V_DATA_DATE              AS   DATA_DATE           
	,M.AREA_NO_ID             AS   AREA_CODE           
	,M.AREA_DSCR              AS   AREA_DESC           
	,R.ORG_ID                 AS   ORG_CODE            
	,R.ORG_DSCR               AS   ORG_NAME            
	,'KPI_TPA_01'             AS   TPA_LOAN_TYPE_CODE  
	,'金融精准扶贫贷款'       AS   TPA_LOAN_TYPE_DESC  
	,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_BAL            
	,SUM(CASE WHEN DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BAL,0) ELSE 0 END)            AS   LOAN_BAL_L          
	,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL_ADD_NEW,0) ELSE 0 END)      AS   LOAN_BAL_ADD_NEW 
	,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END)            AS   LOAN_BAL_Y     
	,SUM(CASE WHEN DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END)          AS   LOAN_BAL_Y_L 
	,0             AS   LOAN_COUNT          
	,0             AS   LOAN_PER_COUNT      
     FROM ODS.GLR_TPA_TYPE_LOAN_DTL1 T 
     LEFT JOIN DMCODE.t_org_biz_lvl R
     ON T.ORG_NO = R.ORG_ID 
     LEFT JOIN DMCODE.t_area_code M
     ON R.AREA_NO_ID = M.AREA_NO_ID 
     where t.rows_id = '8'
     GROUP BY 
         M.AREA_NO_ID 
	,M.AREA_DSCR  
	,R.ORG_ID     
	,R.ORG_DSCR   
     
     UNION ALL 
     
     SELECT
         NOW()                    AS   BATCH_DATA          
	,V_DATA_DATE              AS   DATA_DATE           
	,M.AREA_NO_ID             AS   AREA_CODE           
	,M.AREA_DSCR              AS   AREA_DESC           
	,R.ORG_ID                 AS   ORG_CODE            
	,R.ORG_DSCR               AS   ORG_NAME            
	,'KPI_TPA_02'             AS   TPA_LOAN_TYPE_CODE  
	,'建档立卡贫困人口贷款'       AS   TPA_LOAN_TYPE_DESC  
	,SUM(CASE WHEN T.ROWS_ID = '10' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_BAL            
	,SUM(CASE WHEN T.ROWS_ID = '10' AND DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BAL,0) ELSE 0 END)            AS   LOAN_BAL_L          
	,SUM(CASE WHEN T.ROWS_ID = '10' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL_ADD_NEW,0) ELSE 0 END)      AS   LOAN_BAL_ADD_NEW 
	,SUM(CASE WHEN T.ROWS_ID = '10' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END)            AS   LOAN_BAL_Y     
	,SUM(CASE WHEN T.ROWS_ID = '10' AND DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END)          AS   LOAN_BAL_Y_L 
	,SUM(CASE WHEN T.ROWS_ID = '32' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_COUNT           
	,SUM(CASE WHEN T.ROWS_ID = '33' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_PER_COUNT      
	
     FROM ODS.GLR_TPA_TYPE_LOAN_DTL1 T 
     LEFT JOIN DMCODE.t_org_biz_lvl R
     ON T.ORG_NO = R.ORG_ID 
     LEFT JOIN DMCODE.t_area_code M
     ON R.AREA_NO_ID = M.AREA_NO_ID 
     GROUP BY 
         M.AREA_NO_ID 
	,M.AREA_DSCR  
	,R.ORG_ID     
	,R.ORG_DSCR   
	
     UNION ALL 
     
     
     SELECT
         NOW()                    AS   BATCH_DATA          
	,V_DATA_DATE              AS   DATA_DATE           
	,M.AREA_NO_ID             AS   AREA_CODE           
	,M.AREA_DSCR              AS   AREA_DESC           
	,R.ORG_ID                 AS   ORG_CODE            
	,R.ORG_DSCR               AS   ORG_NAME            
	,'KPI_TPA_03'             AS   TPA_LOAN_TYPE_CODE  
	,'已脱贫人口贷款'   AS   TPA_LOAN_TYPE_DESC  
	,SUM(CASE WHEN T.ROWS_ID = '11' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_BAL            
	,SUM(CASE WHEN T.ROWS_ID = '11' AND DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BAL,0) ELSE 0 END)            AS   LOAN_BAL_L          
	,SUM(CASE WHEN T.ROWS_ID = '11' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL_ADD_NEW,0) ELSE 0 END)      AS   LOAN_BAL_ADD_NEW 
	,SUM(CASE WHEN T.ROWS_ID = '11' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END)            AS   LOAN_BAL_Y     
	,SUM(CASE WHEN T.ROWS_ID = '11' AND DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END)          AS   LOAN_BAL_Y_L 
	,SUM(CASE WHEN T.ROWS_ID = '35' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_COUNT          
	,SUM(CASE WHEN T.ROWS_ID = '36' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_PER_COUNT      
	
     FROM ODS.GLR_TPA_TYPE_LOAN_DTL1 T 
     LEFT JOIN DMCODE.t_org_biz_lvl R
     ON T.ORG_NO = R.ORG_ID 
     LEFT JOIN DMCODE.t_area_code M
     ON R.AREA_NO_ID = M.AREA_NO_ID 
     GROUP BY 
         M.AREA_NO_ID 
	     ,M.AREA_DSCR  
	     ,R.ORG_ID     
	     ,R.ORG_DSCR   
     
     UNION ALL 
     
     
     SELECT
         NOW()                    AS   BATCH_DATA          
	,V_DATA_DATE              AS   DATA_DATE           
	,M.AREA_NO_ID             AS   AREA_CODE           
	,M.AREA_DSCR              AS   AREA_DESC           
	,R.ORG_ID                 AS   ORG_CODE            
	,R.ORG_DSCR               AS   ORG_NAME            
	,'KPI_TPA_04'             AS   TPA_LOAN_TYPE_CODE  
	,'其他个人精准扶贫贷款'   AS   TPA_LOAN_TYPE_DESC  
	,SUM(CASE WHEN T.ROWS_ID = '13' AND DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) ELSE 0 END)              AS   LOAN_BAL            
	,SUM(CASE WHEN T.ROWS_ID = '13' AND DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BAL,0) ELSE 0 END)            AS   LOAN_BAL_L          
