-- PROCEDURE `edw`.`p_sust_a01_ao2_merge`
DROP PROCEDURE IF EXISTS `edw`.`p_sust_a01_ao2_merge`;
DELIMITER $$
CREATE DEFINER=`dwbi`@`%` PROCEDURE `p_sust_a01_ao2_merge`()
BEGIN
  DECLARE v_data_date CHAR(8) DEFAULT DATE_FORMAT(NOW(), '%Y%m%d');
  DELETE
  FROM
    edw.`sust_a01_ao2_merge`
  WHERE DATA_DATE IN
    (SELECT
      a.`DATA_DATE`
    FROM
      ods.`sust_source_of_funds_detailed_a01` a
    WHERE a.`BATCH_DATE` = v_data_date);
  COMMIT;
  
  INSERT INTO edw.`sust_a01_ao2_merge`
  SELECT
    a.DATA_DATE,
    a.ORG_NO,
    t.ORG_DSCR,
    a.L1101,
    a.L1102,
    a.L1103,
    a.L1201,
    a.L1202,
    a.L1203,
    a.L2101,
    a.L2102,
    a.L2103,
    a.L2201,
    a.L2202,
    a.L2203,
    a.L2204,
    a.L2301,
    a.L2302,
    a.L2303,
    a.L2304,
    a.L2401,
    a.L2402,
    a.L2403,
    a.L2501,
    a.L2502,
    a.L2503,
    a.L2504,
    a.L2505,
    a.L2506,
    a.L2507,
    a.L3101,
    a.L3102,
    a.L3103,
    a.L3104,
    b.Y1101,
    b.Y1102,
    b.Y1103,
    b.Y1201,
    b.Y1202,
    b.Y1203,
    b.Y2101,
    b.Y2102,
    b.Y2103,
    b.Y2104_1,
    b.Y2104_2,
    b.Y2104_3,
    b.Y2104_4,
    b.Y2201,
    b.Y2202,
    b.Y2203,
    b.Y2204_1,
    b.Y2204_2,
    b.Y2204_3,
    b.Y2204_4,
    b.Y2204_5,
    b.Y2204_6,
    b.Y2204_7,
    b.Y2204_8,
    b.Y2204_9,
    b.Y2301,
    b.Y2401,
    b.Y2402,
    b.Y2403,
    b.Y2501,
    b.Y2502,
    b.Y2503,
    b.Y2504,
    b.Y2601,
    b.Y2602,
    b.Y2603,
    b.Y2604,
    b.Y2605,
    b.Y2701,
    b.Y2702,
    b.Y2703,
    b.Y2704,
    b.Y2705,
    b.Y2706,
    b.Y2707,
    b.Y2708,
    b.Y2801,
    b.Y2802,
    b.Y2803,
    b.Y2804,
    b.Y2805,
    b.Y2806,
    b.Y2807,
    b.Y3101,
    b.Y3102,
    b.Y3103,
    b.Y3104,
    b.Y3105
  FROM
    ods.sust_source_of_funds_detailed_a01 a
    JOIN ods.sust_source_of_funds_detailed_a02 b
      ON a.ORG_NO = b.ORG_NO
      AND a.L1101 = b.Y1101
      AND a.L1203 = b.Y1203
    LEFT JOIN
      (SELECT
        a.ORG_ID,
        a.ORG_DSCR
      FROM
        dmcode.t_org_biz_lvl a) t
      ON a.ORG_NO = t.ORG_ID
  WHERE a.DATA_DATE IN
    (SELECT
      t.`DATA_DATE`
    FROM
      ods.`sust_source_of_funds_detailed_a01` t
    WHERE t.`BATCH_DATE` = v_data_date);
  COMMIT;
END
$$
DELIMITER ;

-- PROCEDURE `edw`.`p_sust_iq_institutional_assets_and_liabilities`
DROP PROCEDURE IF EXISTS `edw`.`p_sust_iq_institutional_assets_and_liabilities`;
DELIMITER $$
CREATE DEFINER=`dwbi`@`%` PROCEDURE `p_sust_iq_institutional_assets_and_liabilities`()
BEGIN
  DECLARE v_data_date CHAR(8) DEFAULT DATE_FORMAT(NOW(), '%Y%m%d');
  DELETE
  FROM
    edw.`sust_iq_institutional_assets_and_liabilities`
  WHERE DATA_DATE IN
    (SELECT
      a.`DATA_DATE`
    FROM
      ods.`sust_institutional_assets_and_liabilities` a
    WHERE a.`BATCH_DATE` = v_data_date);
  COMMIT;
  INSERT INTO edw.`sust_iq_institutional_assets_and_liabilities`
  SELECT
    a.DATA_DATE,
    a.ORG_NO,
    t.ORG_DSCR,
    a.ROWS_ID,
    a.BATCH_DATE,
    a.CODE,
    a.PROJECT,
    a.FINAL_BALANCE
  FROM
    ods.`sust_institutional_assets_and_liabilities` a
    LEFT JOIN
      (SELECT
        a.ORG_ID,
        a.ORG_DSCR
      FROM
        dmcode.t_org_biz_lvl a) t
      ON a.ORG_NO = t.ORG_ID
      WHERE a.DATA_DATE IN
    (SELECT
      t.`DATA_DATE`
    FROM
      ods.`sust_institutional_assets_and_liabilities` t
    WHERE t.`BATCH_DATE` = v_data_date);
  COMMIT;
END
$$
DELIMITER ;

