-- PROCEDURE `edw`.`p_sust_iq_merge_org_information`
DROP PROCEDURE IF EXISTS `edw`.`p_sust_iq_merge_org_information`;
DELIMITER $$
CREATE DEFINER=`dwbi`@`%` PROCEDURE `p_sust_iq_merge_org_information`()
BEGIN
  DECLARE v_data_date CHAR(8) DEFAULT DATE_FORMAT(NOW(), '%Y%m%d');
  DELETE
  FROM
    edw.`sust_iq_merge_org_information`
  WHERE DATA_DATE IN
    (SELECT
      a.`DATA_DATE`
    FROM
      ods.`sust_essential_information` a
    WHERE a.`BATCH_DATE` = v_data_date);
  COMMIT;
  
  insert into edw.`sust_iq_merge_org_information`
  SELECT
	aa.DATA_DATE,
	aa.ORG_NO,
	t.ORG_DSCR,
	aa.BATCH_DATE,
	aa.PROJECT_NAME,
	aa.PROJECT_1_USCC,
	aa.PROJECT_AREA,
	aa.PROJECT_1_OCI,
	aa.PROJECT_ASSETS,
	aa.PROJECT_1_AS,
	aa.PROJECT_EMMTS,
	aa.PROJECT_1_NOS,
	aa.PROJECT_WORKER,
	aa.PROJECT_1_NOAI,
	bb.NAME,
	bb.NATURE,
	bb.TOTAL,
	bb.PROPORTION
	FROM
	(
	SELECT
	a.AREA_NO,
	a.DATA_DATE,
	a.TABLE_NATURE,
	a.ORG_NO,
	MAX(a.ADD_DATE) AS ADD_DATE,
	'4' AS ROWS_ID,
	a.BATCH_DATE,
	a.SHEET_ID,
	MAX(CASE WHEN a.PROJECT = '机构名称'              THEN a.CONTENT END)   AS PROJECT_NAME,
	MAX(CASE WHEN a.PROJECT_1 = '统一社会信用代码'    THEN a.CONTENT_1 END) AS PROJECT_1_USCC,
	MAX(CASE WHEN a.PROJECT = '机构注册地区'          THEN a.CONTENT END)   AS PROJECT_AREA,
	MAX(CASE WHEN a.PROJECT_1 = '机构联系方式'        THEN a.CONTENT_1 END) AS PROJECT_1_OCI,
	MAX(CASE WHEN a.PROJECT = '机构注册资本（万元）*' THEN a.CONTENT END)   AS PROJECT_ASSETS,
	MAX(CASE WHEN a.PROJECT_1 = '资产规模（万元）'    THEN a.CONTENT_1 END) AS PROJECT_1_AS,
	MAX(CASE WHEN a.PROJECT = '分支机构数'            THEN a.CONTENT END)   AS PROJECT_EMMTS,
	MAX(CASE WHEN a.PROJECT_1 = '控股子公司个数*'     THEN a.CONTENT_1 END) AS PROJECT_1_NOS,
	MAX(CASE WHEN a.PROJECT = '职工人数'              THEN a.CONTENT END)   AS PROJECT_WORKER,
	MAX(CASE WHEN a.PROJECT_1 = '批准机构名称'        THEN a.CONTENT_1 END) AS PROJECT_1_NOAI  
	FROM
	ods.sust_essential_information a
	GROUP BY
	a.AREA_NO,
	a.DATA_DATE,
	a.TABLE_NATURE,
	a.ORG_NO,
	a.BATCH_DATE,
	a.SHEET_ID
	)aa
	LEFT JOIN
	ods.sust_shareholder_information bb
	ON  aa.AREA_NO = bb.AREA_NO
	AND aa.DATA_DATE = bb.DATA_DATE
	AND aa.TABLE_NATURE = bb.TABLE_NATURE
	AND aa.ORG_NO = bb.ORG_NO
	AND aa.BATCH_DATE = bb.BATCH_DATE
	AND aa.SHEET_ID = bb.SHEET_ID
	LEFT JOIN
	      (SELECT
		a.ORG_ID,
		a.ORG_DSCR
	      FROM
		dmcode.t_org_biz_lvl a) t
	      ON aa.ORG_NO = t.ORG_ID
	 WHERE aa.DATA_DATE IN
	    (SELECT
	      t.`DATA_DATE`
	    FROM
	      ods.`sust_essential_information` t
	    WHERE t.`BATCH_DATE` = v_data_date);
    END
$$
DELIMITER ;

-- PROCEDURE `edw`.`P_SUST_SCIENCE_TECHNOLOGY_AND_FINANCE`
DROP PROCEDURE IF EXISTS `edw`.`P_SUST_SCIENCE_TECHNOLOGY_AND_FINANCE`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `P_SUST_SCIENCE_TECHNOLOGY_AND_FINANCE`(in V_BATCH_DATE varchar(10))
BEGIN

	DECLARE DONE             INT DEFAULT FALSE;	
	DECLARE V_DATA_DATE      VARCHAR(10);          
	DECLARE CUR_D_ACCT CURSOR FOR 
	SELECT DISTINCT DATA_DATE  
	FROM ods.sust_science_technology_and_finance
	WHERE BATCH_DATE = V_BATCH_DATE;
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE:= TRUE;
	
	OPEN CUR_D_ACCT;
	ENTLOOP:LOOP
		FETCH CUR_D_ACCT INTO V_DATA_DATE;
		IF DONE THEN
		LEAVE ENTLOOP;
		END IF;

DELETE FROM edw.sust_science_technology_and_finance WHERE DATA_DATE = v_data_date;

INSERT INTO edw.sust_science_technology_and_finance 
SELECT
	a.AREA_NO,
	a.DATA_DATE,
	a.TABLE_NATURE,
	a.ORG_NO,
	a.ADD_DATE,
	a.ROWS_ID,
	a.BATCH_DATE,
	a.SHEET_ID,
	a.KPINAME,
	a.BALANCE,
	a.PREVIOUSBALANCE,
	a.BALANCE-a.PREVIOUSBALANCE     				AS LAST_MONTH,
	ROUND((a.BALANCE-a.PREVIOUSBALANCE)/a.PREVIOUSBALANCE,2) 	AS CHAIN_RATIO,
	a.BALANCE-IFNULL(b.BALANCE,0)					AS OF_YEAR,
	ROUND((a.BALANCE-b.BALANCE)/b.BALANCE,2) 			AS OF_YEAR_RATE,
	a.CHECKTERM
FROM
	ods.sust_science_technology_and_finance a
LEFT JOIN ods.sust_science_technology_and_finance b
	ON DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-%d') = DATE_FORMAT(CONCAT(b.DATA_DATE,'01'),'%Y-01-01')
	AND a.KPINAME = b.KPINAME
WHERE a.DATA_DATE = v_data_date;

DELETE FROM edw.sust_science_technology_and_finance_temp WHERE data_Date = v_data_date;

INSERT INTO edw.sust_science_technology_and_finance_temp
SELECT
	a.AREA_NO,
	a.DATA_DATE,
	a.TABLE_NATURE,
	'000000000000'									AS ORG_NO,
	a.ADD_DATE,
	a.ROWS_ID,
	a.BATCH_DATE,
	a.SHEET_ID,
	a.KPINAME,
	SUM(a.BALANCE) 									AS BALANCE,
	SUM(a.PREVIOUSBALANCE)								AS PREVIOUSBALANCE,
	SUM(a.BALANCE)-SUM(a.PREVIOUSBALANCE)     					AS LAST_MONTH,
	ROUND((SUM(a.BALANCE)-SUM(a.PREVIOUSBALANCE))/SUM(a.PREVIOUSBALANCE),2)		AS CHAIN_RATIO,
	SUM(a.BALANCE)-SUM(b.BALANCE)							AS OF_YEAR,
	ROUND((SUM(a.BALANCE)-SUM(b.BALANCE))/SUM(b.BALANCE),2)				AS OF_YEAR_RATE,
	a.CHECKTERM
FROM
	ods.sust_science_technology_and_finance a
LEFT JOIN ods.sust_science_technology_and_finance b
	ON DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-%d') = DATE_FORMAT(CONCAT(b.DATA_DATE,'01'),'%Y-01-01')
	AND a.KPINAME = b.KPINAME
WHERE a.DATA_DATE = v_data_date
GROUP BY
	a.KPINAME;
	
	


UPDATE edw.sust_science_technology_and_finance_temp temp
SET temp.BALANCE = (
	SELECT 
		ROUND(a.fenzi/b.fenmu,8)
	FROM
	(
		SELECT 
			ROUND(SUM(aa.c),8) AS fenzi 
		FROM 
		( 
		SELECT 
			SUM(CASE WHEN a.ROWS_ID = '55' THEN a.BALANCE END)*
			SUM(CASE WHEN a.ROWS_ID = '58' THEN a.BALANCE END)/100    AS  c
		FROM ods.sust_science_technology_and_finance a
		WHERE a.DATA_DATE = v_data_date
		GROUP BY
			a.DATA_DATE
			,a.ORG_NO
		) aa
	) a
	,
	(
	SELECT 
		SUM(CASE WHEN a.ROWS_ID = '55' THEN a.BALANCE END) AS  fenmu
	 FROM ods.sust_science_technology_and_finance a
	WHERE a.DATA_DATE = v_data_date
	GROUP BY
		a.DATA_DATE
	) b 
),

temp.PREVIOUSBALANCE = (
	SELECT 
		ROUND(a.fenzi/b.fenmu,8)
	FROM
	(
		SELECT 
		ROUND(SUM(aa.c),8) AS fenzi 
		FROM 
		( 
		SELECT 
			SUM(CASE WHEN a.ROWS_ID = '55' THEN a.PREVIOUSBALANCE END)*
			SUM(CASE WHEN a.ROWS_ID = '58' THEN a.PREVIOUSBALANCE END)/100    AS  c
		 FROM ods.sust_science_technology_and_finance a
		WHERE a.DATA_DATE = v_data_date
		GROUP BY
		    a.DATA_DATE
		   ,a.ORG_NO
		) aa
	) a
	,
	(
	SELECT 
		SUM(CASE WHEN a.ROWS_ID = '55' THEN a.PREVIOUSBALANCE END) AS  fenmu
	 FROM ods.sust_science_technology_and_finance a
	WHERE a.DATA_DATE = v_data_date
	GROUP BY
	    a.DATA_DATE
	) b
)
WHERE
	temp.DATA_DATE = v_data_date 
	AND temp.ROWS_ID = '58';
	
	

UPDATE edw.sust_science_technology_and_finance_temp a
  JOIN edw.sust_science_technology_and_finance_temp b
    ON DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-%d') = DATE_FORMAT(CONCAT(b.DATA_DATE,'01'),'%Y-01-01')
   AND a.KPINAME = b.KPINAME
SET a.LAST_MONTH = (a.BALANCE-a.PREVIOUSBALANCE),
    a.CHAIN_RATIO = round((a.BALANCE-a.PREVIOUSBALANCE)/a.PREVIOUSBALANCE,2),
    a.OF_YEAR = a.BALANCE-b.BALANCE,
    a.OF_YEAR_RATE = round((a.BALANCE-b.BALANCE)/b.BALANCE,2)
WHERE a.data_date = v_data_date
  AND a.ROWS_ID = '58';
  
  

UPDATE edw.sust_science_technology_and_finance_temp  a
SET a.BALANCE = 
   (
	SELECT 
	MIN(r.BALANCE) 
	FROM edw.sust_science_technology_and_finance r
	WHERE DATA_DATE = V_DATA_DATE
	AND r.ROWS_ID = '59'
	AND r.ORG_NO <> '000000000000'
    )
WHERE A.DATA_DATE = V_DATA_DATE
AND a.ROWS_ID = '59';

UPDATE edw.sust_science_technology_and_finance_temp  a
SET a.BALANCE = 
(
	SELECT 
	MAX(r.BALANCE) 
	FROM edw.sust_science_technology_and_finance r
	WHERE R.DATA_DATE = V_DATA_DATE
  AND	r.ROWS_ID = '60'
	AND r.ORG_NO <> '000000000000'
)
WHERE A.DATA_DATE = V_DATA_DATE
AND a.ROWS_ID = '60';

DELETE FROM edw.sust_science_technology_and_finance 
WHERE DATA_DATE = v_data_date
and ORG_NO = '000000000000';

INSERT INTO edw.sust_science_technology_and_finance 
SELECT * FROM edw.sust_science_technology_and_finance_temp
WHERE data_date = v_data_date;
	END LOOP ENTLOOP;
	CLOSE CUR_D_ACCT;
	END
$$
DELIMITER ;

