-- PROCEDURE `edw`.`p_sust_use_of_funds_d02_fact`
DROP PROCEDURE IF EXISTS `edw`.`p_sust_use_of_funds_d02_fact`;
DELIMITER $$
CREATE DEFINER=`dwbi`@`%` PROCEDURE `p_sust_use_of_funds_d02_fact`()
BEGIN
DELETE FROM edw.sust_use_of_funds_d02_fact;
commit;
insert into edw.sust_use_of_funds_d02_fact
SELECT
  '2017第一季度' AS DATA_DATE,
  a.ORG_NO,
  t.ORG_DSCR,
  a.ROWS_ID,
  a.BATCH_DATE,
  a.PROJECT,
  a.BALANCE1 AS BALANCE,
  a.INTEREST_RATE1 AS INTEREST_RATE,
  a.RATE1 AS RATE
FROM
  ods.`sust_use_of_funds_d02` a
  LEFT JOIN
    (SELECT
      a.ORG_ID,
      a.ORG_DSCR
    FROM
      dmcode.t_org_biz_lvl a) t
    ON a.ORG_NO = t.ORG_ID
UNION
ALL
SELECT
  '2017第二季度' AS DATA_DATE,
  a.ORG_NO,
  t.ORG_DSCR,
  a.ROWS_ID,
  a.BATCH_DATE,
  a.PROJECT,
  a.BALANCE2 AS BALANCE,
  a.INTEREST_RATE2 AS INTEREST_RATE,
  a.RATE2 AS RATE
FROM
  ods.`sust_use_of_funds_d02` a
  LEFT JOIN
    (SELECT
