-- PROCEDURE `edw`.`p_transDataFromOdsToEdw_main`
DROP PROCEDURE IF EXISTS `edw`.`p_transDataFromOdsToEdw_main`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `p_transDataFromOdsToEdw_main`()
BEGIN
  DECLARE flag INT DEFAULT FALSE;
  DECLARE areaNo VARCHAR (8);
  DECLARE dataDate CHAR (8);
  DECLARE TABLE_NATURE VARCHAR (50);
  DECLARE orgNo VARCHAR (53);
  DECLARE ADD_DATE TIMESTAMP;
  DECLARE rowsId VARCHAR (100);
  DECLARE BATCH_DATE CHAR (8);
  DECLARE SHEET_ID VARCHAR (100);
  DECLARE OCCURRENCE_ORG VARCHAR (512);
  DECLARE BWBDEPOSIT varchar (40);
  DECLARE RMBDEPOSIT VARCHAR (40);
  DECLARE SAVINGSDEPOSIT VARCHAR (40);
  DECLARE BWBLOAN VARCHAR (40);
  DECLARE RMBLOAN VARCHAR (40);
  DECLARE SHORTTERMLOAN VARCHAR (40);
  DECLARE MEDIUMLONGTERMLOAN VARCHAR (40);
  DECLARE PERSONALMLTERMLOAN VARCHAR (40);
  DECLARE cur CURSOR FOR
  (SELECT
    *
  FROM
    ods.sust_main_indicators_of_institutions
  WHERE 1 = 1 
  );
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET flag = TRUE;
  OPEN cur;
  posLoop :
  LOOP
    FETCH cur INTO areaNo,
    dataDate,
    TABLE_NATURE,
    orgNo,
    ADD_DATE,
    rowsId,
    BATCH_DATE,
    SHEET_ID,
    OCCURRENCE_ORG,
    BWBDEPOSIT,
    RMBDEPOSIT,
    SAVINGSDEPOSIT,
    BWBLOAN,
    RMBLOAN,
    SHORTTERMLOAN,
    MEDIUMLONGTERMLOAN,
    PERSONALMLTERMLOAN;
    IF flag
    THEN LEAVE posLoop;
    END IF;
    
    DELETE
    FROM
      edw.sust_main_indicators_of_institutions
    WHERE AREA_NO = areaNo
      AND ORG_NO = orgNo
      AND DATA_DATE = dataDate
      and ROWS_ID = rowsId; 
      
    INSERT INTO edw.sust_main_indicators_of_institutions
    VALUES
      (
        areaNo,
        dataDate,
        TABLE_NATURE,
        orgNo,
        ADD_DATE,
        rowsId,
        BATCH_DATE,
        SHEET_ID,
        OCCURRENCE_ORG,
        BWBDEPOSIT,
        RMBDEPOSIT,
        SAVINGSDEPOSIT,
        BWBLOAN,
        RMBLOAN,
        SHORTTERMLOAN,
        MEDIUMLONGTERMLOAN,
        PERSONALMLTERMLOAN
      );
  END LOOP;
  CLOSE cur;
  COMMIT;
END
$$
DELIMITER ;

-- PROCEDURE `edw`.`P_TRS_BUDGET_INCOME_COMPARE`
DROP PROCEDURE IF EXISTS `edw`.`P_TRS_BUDGET_INCOME_COMPARE`;
DELIMITER $$
CREATE DEFINER=`dis`@`%` PROCEDURE `P_TRS_BUDGET_INCOME_COMPARE`(IN P_DATA_DATE VARCHAR(10))
BEGIN
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'EDW.P_TRS_BUDGET_INCOME_COMPARE.PRC';
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE S_DATA_DATE     VARCHAR(8)	DEFAULT	DATE_FORMAT(P_DATA_DATE,'%Y-%m');
  
  DECLARE done INT DEFAULT 0;
  DECLARE V_DATA_DATE     VARCHAR(8);
  DECLARE cur CURSOR FOR
  SELECT DISTINCT data_date FROM stg.trs_tmis_budget_income_provinces WHERE batch_date = P_DATA_DATE ORDER BY data_date;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
 
     DECLARE EXIT HANDLER FOR SQLEXCEPTION
   BEGIN
       GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
       CALL ETL.EDW_PROC_ERROR_LOG(S_DATA_DATE,V_START_TIME,NOW(),TABLE_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
   END; 
  
  
  OPEN cur;
  WHILE
    done <> 1 DO FETCH cur INTO V_DATA_DATE;
    IF done <> 1
    THEN 
select V_DATA_DATE;    
    SET V_STEP_ID = 1;
    
DELETE FROM EDW.TRS_BUDGET_INCOME_COMPARE WHERE DATA_DATE = V_DATA_DATE;
SET V_STEP_ID = 2;
insert into EDW.TRS_BUDGET_INCOME_COMPARE
SELECT 
	 DATA_DATE
	,PROJECT
	,ROUND (SUM(T010101_RATE),4)
	,SUM(T010101_RANK)
	,ROUND (SUM(101_TATE),4)
	,SUM(101_RANK)
	,ROWS_ID
FROM 
(
SELECT 
	AA.DATA_DATE,
	AA.PROJECT,
	AA.T010101_RATE,
	@rank:=@rank+1 AS T010101_RANK,
	AA.101_TATE,
	AA.101_RANK,
	AA.ROWS_ID
FROM 
(
SELECT 
	a.DATA_DATE,
	CASE WHEN a.TREDSCR = '大连市' THEN '辽宁'
             WHEN a.TREDSCR = '青岛市' THEN '山东省' 
	     WHEN a.TREDSCR = '深圳市' THEN '广东省'
             WHEN a.TREDSCR = '宁波市' THEN '浙江省'
             WHEN a.TREDSCR = '厦门市' THEN '福建省'
             WHEN (a.TREDSCR = '新疆兵团' or a.TREDSCR = '新疆区') THEN '新疆区'
	     ELSE a.TREDSCR
	     END  AS PROJECT,
	(SUM(a.YEAR_AMT)-SUM(b.YEAR_AMT))/SUM(b.YEAR_AMT) AS T010101_RATE,
	'' AS 101_TATE,
	'' AS 101_RANK,
        A.ROWS_ID
FROM stg.trs_tmis_budget_income_provinces a
LEFT JOIN stg.trs_tmis_budget_income_provinces b
       ON b.data_Date = DATE_FORMAT(DATE_SUB(CONCAT(a.data_Date,'01'),INTERVAL 1 YEAR),'%Y%m')
       AND a.TRECODE = b.TRECODE
       AND a.SUBJECT_CODE = b.SUBJECT_CODE
WHERE a.data_Date = V_DATA_DATE
AND a.SUBJECT_CODE = 'T010101'
GROUP BY
        CASE WHEN a.TRECODE = '3501000000' THEN '0600000000'
             WHEN a.TRECODE = '3302000000' THEN '1500000000' 
	     WHEN a.TRECODE = '3801000000' THEN '1900000000'
             WHEN a.TRECODE = '3600000000' THEN '1100000000'
             WHEN a.TRECODE = '4000000000' THEN '1300000000'
						 WHEN (a.TRECODE = '3100000000' or a.TRECODE = '3000000000')  THEN '3000000000'
	     ELSE a.TRECODE
	     END
ORDER BY T010101_RATE  DESC
) AA ,(SELECT @rank:=0) BB
UNION ALL
(
SELECT 
	AA.DATA_DATE,
	AA.PROJECT,
	AA.T010101_RATE,
	AA.T010101_RANK,
	AA.101_TATE,
	@rank2:=@rank2+1  AS 101_RANK,
	AA.ROWS_ID
FROM 
(
SELECT 
	a.DATA_DATE,
	CASE WHEN a.TREDSCR = '大连市' THEN '辽宁'
             WHEN a.TREDSCR = '青岛市' THEN '山东省' 
	     WHEN a.TREDSCR = '深圳市' THEN '广东省'
             WHEN a.TREDSCR = '宁波市' THEN '浙江省'
             WHEN a.TREDSCR = '厦门市' THEN '福建省'
             WHEN (a.TREDSCR = '新疆兵团' or a.TREDSCR = '新疆区') THEN '新疆区'
	     ELSE a.TREDSCR
	     END  AS PROJECT,
	'' AS T010101_RATE,
	'' AS T010101_RANK,
	(SUM(a.YEAR_AMT)-SUM(b.YEAR_AMT))/SUM(b.YEAR_AMT) AS 101_TATE,
	A.ROWS_ID
FROM stg.trs_tmis_budget_income_provinces a
LEFT JOIN stg.trs_tmis_budget_income_provinces b
       ON b.data_Date = DATE_FORMAT(DATE_SUB(CONCAT(a.data_Date,'01'),INTERVAL 1 YEAR),'%Y%m')
       AND a.TRECODE = b.TRECODE
       AND a.SUBJECT_CODE = b.SUBJECT_CODE
,(SELECT @tate:=NULL,@rank:=0) c
WHERE A.DATA_DATE = V_DATA_DATE
AND a.SUBJECT_CODE = '101'
GROUP BY
        CASE WHEN a.TRECODE = '3501000000' THEN '0600000000'
             WHEN a.TRECODE = '3302000000' THEN '1500000000' 
	     WHEN a.TRECODE = '3801000000' THEN '1900000000'
             WHEN a.TRECODE = '3600000000' THEN '1100000000'
             WHEN a.TRECODE = '4000000000' THEN '1300000000'
						 WHEN (a.TRECODE = '3100000000' or a.TRECODE = '3000000000')  THEN '3000000000'
	     ELSE a.TRECODE
	     END
ORDER BY 101_TATE DESC
) AA ,(SELECT @rank2:=0) BB
) 
)A
GROUP BY 
        PROJECT;
        
 SET V_STEP_ID = 3;       
DELETE FROM EDW.TRS_BUDGET_INCOME_COMPARE WHERE DATA_DATE = concat(year(concat(V_DATA_DATE,'01')),'Q',quarter(CONCAT(V_DATA_DATE,'01')));
 SET V_STEP_ID = 4;
INSERT INTO EDW.TRS_BUDGET_INCOME_COMPARE
SELECT 
	 DATA_DATE
	,PROJECT
	,ROUND (SUM(T010101_RATE),4)
	,SUM(T010101_RANK)
	,ROUND (SUM(101_TATE),4)
	,SUM(101_RANK)
	,ROWS_ID
FROM 
(
SELECT 
	CONCAT(YEAR(CONCAT(AA.data_Date,'01')),'Q',QUARTER(CONCAT(AA.data_Date,'01'))) AS DATA_DATE,
	AA.PROJECT,
	AA.T010101_RATE,
	@rank:=@rank+1 AS T010101_RANK,
	AA.101_TATE,
	AA.101_RANK,
	AA.ROWS_ID
FROM 
(
SELECT 
	a.DATA_DATE,
	CASE WHEN a.TREDSCR = '大连市' THEN '辽宁'
             WHEN a.TREDSCR = '青岛市' THEN '山东省' 
	     WHEN a.TREDSCR = '深圳市' THEN '广东省'
             WHEN a.TREDSCR = '宁波市' THEN '浙江省'
             WHEN a.TREDSCR = '厦门市' THEN '福建省'
             WHEN (a.TREDSCR = '新疆兵团' or a.TREDSCR = '新疆区') THEN '新疆区'
	     ELSE a.TREDSCR
	     END  AS PROJECT,
	(SUM(a.YEAR_AMT)-SUM(b.YEAR_AMT))/SUM(b.YEAR_AMT) AS T010101_RATE,
	'' AS 101_TATE,
	'' AS 101_RANK,
        A.ROWS_ID
FROM stg.trs_tmis_budget_income_provinces a
LEFT JOIN stg.trs_tmis_budget_income_provinces b
       ON b.data_Date = DATE_FORMAT(DATE_SUB(CONCAT(a.data_Date,'01'),INTERVAL 1 YEAR),'%Y%m')
       AND a.TRECODE = b.TRECODE
       AND a.SUBJECT_CODE = b.SUBJECT_CODE
WHERE a.data_Date = V_DATA_DATE
AND a.SUBJECT_CODE = 'T010101'
GROUP BY
        CASE WHEN a.TRECODE = '3501000000' THEN '0600000000'
             WHEN a.TRECODE = '3302000000' THEN '1500000000' 
	     WHEN a.TRECODE = '3801000000' THEN '1900000000'
             WHEN a.TRECODE = '3600000000' THEN '1100000000'
             WHEN a.TRECODE = '4000000000' THEN '1300000000'
						 WHEN (a.TRECODE = '3100000000' or a.TRECODE = '3000000000')  THEN '3000000000'
	     ELSE a.TRECODE
	     END
ORDER BY T010101_RATE  DESC
) AA ,(SELECT @rank:=0) BB
UNION ALL
(
SELECT 
	CONCAT(YEAR(CONCAT(AA.data_Date,'01')),'Q',QUARTER(CONCAT(AA.data_Date,'01'))) AS DATA_DATE,
	AA.PROJECT,
	AA.T010101_RATE,
	AA.T010101_RANK,
	AA.101_TATE,
	@rank2:=@rank2+1  AS 101_RANK,
	AA.ROWS_ID
FROM 
(
SELECT 
	a.DATA_DATE,
	CASE WHEN a.TREDSCR = '大连市' THEN '辽宁'
             WHEN a.TREDSCR = '青岛市' THEN '山东省' 
	     WHEN a.TREDSCR = '深圳市' THEN '广东省'
             WHEN a.TREDSCR = '宁波市' THEN '浙江省'
             WHEN a.TREDSCR = '厦门市' THEN '福建省'
             WHEN (a.TREDSCR = '新疆兵团' or a.TREDSCR = '新疆区') THEN '新疆区'
	     ELSE a.TREDSCR
	     END  AS PROJECT,
	'' AS T010101_RATE,
	'' AS T010101_RANK,
	(SUM(a.YEAR_AMT)-SUM(b.YEAR_AMT))/SUM(b.YEAR_AMT) AS 101_TATE,
	A.ROWS_ID
FROM stg.trs_tmis_budget_income_provinces a
LEFT JOIN stg.trs_tmis_budget_income_provinces b
       ON b.data_Date = DATE_FORMAT(DATE_SUB(CONCAT(a.data_Date,'01'),INTERVAL 1 YEAR),'%Y%m')
       AND a.TRECODE = b.TRECODE
       AND a.SUBJECT_CODE = b.SUBJECT_CODE
,(SELECT @tate:=NULL,@rank:=0) c
WHERE a.data_Date =V_DATA_DATE
AND a.SUBJECT_CODE = '101'
GROUP BY
        CASE WHEN a.TRECODE = '3501000000' THEN '0600000000'
             WHEN a.TRECODE = '3302000000' THEN '1500000000' 
	     WHEN a.TRECODE = '3801000000' THEN '1900000000'
             WHEN a.TRECODE = '3600000000' THEN '1100000000'
             WHEN a.TRECODE = '4000000000' THEN '1300000000'
						 WHEN (a.TRECODE = '3100000000' or a.TRECODE = '3000000000')  THEN '3000000000'
	     ELSE a.TRECODE
	     END
ORDER BY 101_TATE DESC
) AA ,(SELECT @rank2:=0) BB
) 
)A
GROUP BY 
        PROJECT;
    END IF;
  END WHILE;
  CLOSE cur;
	END
$$
DELIMITER ;

